class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = monthly_limit_mib * 1024 * 1024
        self._uploads: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("Upload size must be positive")

        uploads = self._uploads.get(month, {})
        if name in uploads:
            return

        if sum(uploads.values()) + size_bytes > self._limit_bytes:
            raise ValueError("Monthly upload quota exceeded")

        self._uploads.setdefault(month, {})[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Deletion does not remove the upload from the month's quota history.
        pass

    def used_bytes(self, month: str) -> int:
        return sum(self._uploads.get(month, {}).values())
